const paths={leaf:'<path d="M19 3C8 3 3 8 5 15c2 6 13 6 14-12Z"/><path d="M5 20 15 9M9 14v-4"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15"/>',school:'<path d="m3 9 9-6 9 6M5 9v11h14V9M3 20h18M10 20v-5h4v5M9 10h0M15 10h0"/>',chart:'<path d="M4 3v17h17M8 15l4-6 4 3 5-7"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',logout:'<path d="M9 4H4v16h5M9 12h12m-5-5 5 5-5 5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',check:'<path d="m5 12 4 4 10-10"/>'};
const icon=n=>`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true">${paths[n]}</svg>`,escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brand=()=>`<div class="brand"><span class="brand-mark">${icon('leaf')}</span><div>成长档案<small>ADMIN CONSOLE</small></div></div>`;
const parents=Array.from({length:8},(_,i)=>({id:`p${i+1}`,phone:`1380000${String(1001+i).padStart(4,'0')}`,date:`2026-09-${String(3+i*2).padStart(2,'0')}`}));
const names=['林小禾','陈亦安','周予宁','许知远','王沐阳','赵书瑶','沈嘉禾','李星辰','陈一诺','周子墨','许安然','林知夏'];
const students=names.map((name,i)=>({id:`s${i+1}`,parent:parents[i%8].id,name,gender:i%2?'男':'女',school:['实验小学','育才小学','文正小学'][i%3],grade:['六年级','五年级','四年级'][i%3],year:2021+i%3,entry:'一年级'}));
const exams=students.flatMap((s,i)=>['开学测评','九月阶段练习','十月月考'].map((name,j)=>({id:`e${i}-${j}`,student:s.id,name,date:['2026-09-08','2026-09-23','2026-10-09'][j],note:j===2?'已由家长自主填报。':'',subjects:['语文','数学','英语'].map((name,k)=>({name,type:'score',max:100,score:76+(i*5+j*3+k*7)%24})).concat([{name:'科学',type:'grade',grade:['A','B','A','C'][(i+j)%4]}])})));
const levels=['优先考虑','备选学校','了解中'],schoolNames=['市实验中学','育才中学','文正中学','第一中学'];
const intents=students.flatMap((s,i)=>Array.from({length:i%2?1:2},(_,j)=>({id:`i${i}-${j}`,student:s.id,name:schoolNames[(i+j)%4],level:levels[(i+j)%3],note:['关注校园开放日','了解课程设置','了解通勤安排'][i%3]})));
const scoreRows=exams.flatMap(e=>e.subjects.map((s,i)=>({...s,id:`${e.id}-${i}`,exam:e})));let screen='overview',chartMode='subject',currentPage=1,filters={},menuOpen=false;const root=document.getElementById('admin-app'),drawerRoot=document.getElementById('drawer-root');
const studentBy=id=>students.find(s=>s.id===id),parentBy=s=>parents.find(p=>p.id===s.parent),parentPhone=s=>parentBy(s).phone;
const titles={overview:'数据概览',families:'家长与学生',scores:'成绩记录',intents:'意向学校',analysis:'汇总分析'};
function notify(msg){let t=document.getElementById('admin-toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.nt);window.nt=setTimeout(()=>t.classList.remove('show'),2500)}
function logged(){try{return sessionStorage.getItem('admin-demo-session')==='1'}catch{return false}}
function loginPage(){root.innerHTML=`<main class="login"><section class="login-story">${brand()}<div class="story-copy"><div class="eyebrow">A CLEARER VIEW OF EVERY STEP</div><h1>让每一份记录<br>成为成长的参照。</h1><p>连接孩子的成绩与期待，<br>让数据清晰，让陪伴更有方向。</p><div class="story-points"><span>${icon('shield')} 独立管理员入口</span><span>${icon('chart')} 全局数据视图</span></div></div><svg class="story-art" viewBox="0 0 360 350" aria-hidden="true"><circle cx="250" cy="240" r="170" fill="none" stroke="#6c936c"/><circle cx="250" cy="240" r="130" fill="none" stroke="#6c936c"/><path d="M195 330Q180 230 245 112M215 203Q155 175 166 145Q219 151 215 203M227 172Q292 171 297 132Q247 126 227 172M198 252Q144 221 148 195Q203 205 198 252M205 228Q266 244 286 206Q234 188 205 228" stroke="#dcebaa" stroke-width="2" fill="#91b170" fill-opacity=".18"/><path d="m94 110 5 13 13 5-13 5-5 13-5-13-13-5 13-5Z" fill="#dcebaa"/><circle cx="310" cy="95" r="5" fill="#dcebaa"/></svg><div class="story-foot">成长档案 / 家长自主填报与意向采集平台</div></section><section class="login-panel"><a class="back-parent" href="/">返回家长端 ↗</a><div class="login-form-wrap"><div class="eyebrow">WELCOME BACK</div><h1>管理员登录</h1><p class="login-sub">登录管理工作台，查看成绩与招生意向数据。</p><form id="login-form"><label class="field"><span>管理员账号</span><input name="username" autocomplete="username" placeholder="请输入管理员账号" required></label><label class="field"><span>登录密码</span><div class="password-wrap"><input name="password" type="password" autocomplete="current-password" placeholder="请输入登录密码" required><button type="button" class="password-toggle" data-action="toggle-password" aria-label="显示密码">${icon('eye')}</button></div></label><div class="error" id="login-error" role="alert"></div><button class="primary" type="submit">登录管理后台 ${icon('arrow')}</button></form><div class="login-check">${icon('shield')} 管理员账号独立于家长账号</div><div class="demo-box">交互原型 · 使用虚构数据<br>体验账号：admin / 密码：demo123<button data-action="fill-demo">填入体验账号</button><br>此登录仅演示页面流程，未连接认证服务。</div></div></section></main>`}
function navigate(s){screen=s;currentPage=1;filters={};menuOpen=false;render();window.scrollTo(0,0)}
function stats(){return `<div class="stat-grid">${[['注册家长数',parents.length,'位','独立家长账号','users'],['在册学生数',students.length,'位','学生档案均已建档','book'],['累计成绩记录',scoreRows.length,'条',`${exams.length} 个考试批次 · 按科目计数`,'chart'],['有效意向数',intents.length,'条',`${new Set(intents.map(i=>i.student)).size} 位学生已填写意向`,'school']].map(([title,num,unit,note,i])=>`<div class="stat-card"><div class="stat-label">${title}<span class="stat-icon">${icon(i)}</span></div><div class="stat-value">${num}<small>${unit}</small></div><div class="stat-note"><span class="dot"></span>${note}</div></div>`).join('')}</div>`}
function subjectChart(){let avg=['语文','数学','英语'].map(name=>{let a=scoreRows.filter(r=>r.type==='score'&&r.name===name);return {name,avg:a.reduce((n,r)=>n+r.score/r.max*100,0)/a.length}});return `<svg class="chart-svg" viewBox="0 0 550 220" role="img" aria-label="各科平均得分率柱状图">${[0,25,50,75,100].map(v=>`<line x1="42" x2="535" y1="${175-v*1.4}" y2="${175-v*1.4}" stroke="#eef1e7" stroke-dasharray="3 4"/><text x="3" y="${179-v*1.4}" font-size="10" fill="#98a28e">${v}%</text>`).join('')}${avg.map((v,i)=>`<rect x="${100+i*155}" y="${175-v.avg*1.4}" width="52" height="${v.avg*1.4}" rx="5" fill="${['#60865e','#8fab72','#c7dca1'][i]}"/><text x="${126+i*155}" y="${164-v.avg*1.4}" text-anchor="middle" font-size="12" fill="#5d7650">${v.avg.toFixed(1)}%</text><text x="${126+i*155}" y="202" text-anchor="middle" font-size="11" fill="#8a9782">${v.name}</text>`).join('')}</svg><div class="legend"><span><i></i>平均得分率</span></div>`}
function batchChart(){const ds=['2026-09-08','2026-09-23','2026-10-09'],counts=ds.map(d=>exams.filter(e=>e.date===d).length);return `<svg class="chart-svg" viewBox="0 0 550 220" role="img" aria-label="考试录入日期分布">${[0,5,10,15].map(v=>`<line x1="42" x2="530" y1="${175-v*9}" y2="${175-v*9}" stroke="#eef1e7"/><text x="12" y="${179-v*9}" fill="#98a28e" font-size="10">${v}</text>`).join('')}${counts.map((v,i)=>`<rect x="${100+i*155}" y="${175-v*9}" width="50" height="${v*9}" rx="5" fill="#8eaa72"/><text x="${125+i*155}" y="${163-v*9}" text-anchor="middle" fill="#608052" font-size="12">${v} 次</text><text x="${125+i*155}" y="202" text-anchor="middle" fill="#8a9782" font-size="10">${ds[i].slice(5)}</text>`).join('')}</svg><div class="legend"><span><i></i>考试批次数</span></div>`}
function gradeDonut(){let data=['A','B','C','D'].map(g=>scoreRows.filter(r=>r.type==='grade'&&r.grade===g).length),sum=data.reduce((a,b)=>a+b,0),colors=['#62885c','#a8bf82','#d5dfb6','#e9e9dc'],offset=0;return `<div class="donut-wrap"><svg class="donut" viewBox="0 0 160 160" role="img" aria-label="科学科目等级分布"><circle cx="80" cy="80" r="57" fill="none" stroke="#f1f4ea" stroke-width="17"/>${data.map((v,i)=>{let len=v/sum*358.14,o=offset;offset+=len;return `<circle cx="80" cy="80" r="57" fill="none" stroke="${colors[i]}" stroke-width="17" stroke-dasharray="${len} ${358.14-len}" stroke-dashoffset="${-o}" transform="rotate(-90 80 80)"/>`}).join('')}<text x="80" y="78" text-anchor="middle" font-size="25" fill="#334a37">${sum}</text><text x="80" y="98" text-anchor="middle" font-size="10" fill="#98a28e">等级成绩</text></svg><div class="donut-legend">${data.map((v,i)=>`<div><span><i style="background:${colors[i]}"></i>${['A','B','C','D'][i]} 等级</span><strong>${v}</strong></div>`).join('')}</div></div><div class="donut-foot">科学 · 按等级标签计数，不换算为分数</div>`}
function schoolBars(){let counts=schoolNames.map(name=>({name,count:new Set(intents.filter(i=>i.name===name).map(i=>i.student)).size})).sort((a,b)=>b.count-a.count),max=Math.max(...counts.map(c=>c.count));return counts.map((s,i)=>`<div class="school-bar"><div class="bar-top"><span><span class="muted">0${i+1}</span>　${s.name}</span><span>${s.count} 位学生</span></div><div class="bar-track"><div class="bar-fill" style="width:${s.count/max*100}%;background:${['#66895c','#8dab70','#b2c990','#d6e0b9'][i]}"></div></div></div>`).join('')}
function chartPanels(){return `<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>${chartMode==='subject'?'各科平均得分率':'考试日期分布'}</h2><p>${chartMode==='subject'?'分数制成绩按满分归一化，便于查看整体分布':'按考试日期汇总批次数，不代表填报日期'}</p></div><div class="chart-tabs"><button data-action="chart" data-value="subject" class="${chartMode==='subject'?'active':''}">科目</button><button data-action="chart" data-value="batch" class="${chartMode==='batch'?'active':''}">考试</button></div></div><div class="panel-body">${chartMode==='subject'?subjectChart():batchChart()}</div></section><section class="panel"><div class="panel-head"><div><h2>等级成绩分布</h2><p>只统计等级制科目</p></div><span class="tag gray">科学</span></div><div class="panel-body">${gradeDonut()}</div></section></div>`}
function studentRow(s){return `<tr><td><div class="table-person"><span class="avatar">${s.name.slice(-1)}</span><strong>${s.name}</strong></div></td><td>${parentPhone(s)}</td><td>${s.school}</td><td><span class="tag gray">${s.grade}</span></td><td>${exams.filter(e=>e.student===s.id).length} 次</td><td>${intents.filter(i=>i.student===s.id).length} 条</td><td><button class="table-link" data-action="student-detail" data-id="${s.id}">查看详情 ›</button></td></tr>`}
function overview(){return `${stats()}${chartPanels()}<div class="dashboard-grid"><section class="panel panel-table"><div class="panel-head"><div><h2>最近考试关联学生</h2><p>查看学生档案及对应的家长信息</p></div><button class="table-link" data-action="nav" data-value="families">全部学生 ›</button></div><div class="table-wrap"><table><thead><tr>${['学生姓名','家长手机号','就读学校','当前年级','考试','意向','操作'].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${students.slice(0,4).map(studentRow).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>意向学校热度</h2><p>按学校汇总意向学生数</p></div><button class="table-link" data-action="nav" data-value="intents">明细 ›</button></div><div class="panel-body">${schoolBars()}</div></section></div>`}
function filterHTML(){return `<form class="filters" id="filter-form"><div class="filter-field"><label for="filter-phone">家长手机号</label><input id="filter-phone" name="phone" type="search" value="${escapeHTML(filters.phone)}" placeholder="输入手机号，支持部分匹配"></div><div class="filter-field"><label for="filter-school">就读学校</label><select id="filter-school" name="school"><option value="">全部学校</option>${[...new Set(students.map(s=>s.school))].map(s=>`<option ${filters.school===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="filter-field"><label for="filter-grade">当前年级</label><select id="filter-grade" name="grade"><option value="">全部年级</option>${['四年级','五年级','六年级'].map(g=>`<option ${filters.grade===g?'selected':''}>${g}</option>`).join('')}</select></div><button class="primary" type="submit">${icon('search')} 查询</button><button class="secondary" type="button" data-action="reset-filters">重置</button></form>`}
function matches(s){return (!filters.phone||parentPhone(s).includes(filters.phone))&&(!filters.school||s.school===filters.school)&&(!filters.grade||s.grade===filters.grade)}
function filteredRows(){if(screen==='families')return students.filter(matches);if(screen==='scores')return scoreRows.filter(r=>matches(studentBy(r.exam.student)));if(screen==='intents')return intents.filter(i=>matches(studentBy(i.student)));return []}
function pagination(total){let pages=Math.max(1,Math.ceil(total/8));currentPage=Math.min(currentPage,pages);return `<div class="pagination"><span>共 ${total} 条 · 每页 8 条</span><div class="page-buttons"><button data-action="page" data-value="${currentPage-1}" ${currentPage===1?'disabled':''} aria-label="上一页">‹</button>${Array.from({length:pages},(_,i)=>i+1).filter(n=>n===1||n===pages||Math.abs(n-currentPage)<=1).map((n,i,a)=>`${i&&n-a[i-1]>1?'<span>…</span>':''}<button data-action="page" data-value="${n}" class="${currentPage===n?'active':''}" aria-label="第 ${n} 页">${n}</button>`).join('')}<button data-action="page" data-value="${currentPage+1}" ${currentPage===pages?'disabled':''} aria-label="下一页">›</button></div></div>`}
function listPage(){let all=filteredRows(),pager=pagination(all.length),rows=all.slice((currentPage-1)*8,currentPage*8);let heads=screen==='families'?['学生姓名','家长手机号','就读学校','当前年级','考试','意向','操作']:screen==='scores'?['学生 / 家长手机号','就读学校 / 年级','考试名称','考试日期','科目','成绩类型','成绩','操作']:['意向学校','意向等级','学生姓名','家长手机号','就读学校','当前年级','备注','操作'];let body=rows.map(r=>{if(screen==='families')return studentRow(r);if(screen==='scores'){let s=studentBy(r.exam.student);return `<tr><td><strong>${s.name}</strong><div class="table-date" style="margin-top:6px">${parentPhone(s)}</div></td><td>${s.school}<div class="table-date" style="margin-top:6px">${s.grade}</div></td><td>${r.exam.name}</td><td class="table-date">${r.exam.date}</td><td>${r.name}</td><td><span class="tag ${r.type==='grade'?'amber':'gray'}">${r.type==='score'?'分数制':'等级制'}</span></td><td><strong>${r.type==='score'?r.score:r.grade}</strong>${r.type==='score'?`<span class="muted"> / ${r.max}</span>`:''}</td><td><button class="table-link" data-action="exam-detail" data-id="${r.exam.id}">查看 ›</button></td></tr>`}let s=studentBy(r.student);return `<tr><td><strong>${r.name}</strong></td><td><span class="tag ${r.level==='了解中'?'gray':r.level==='备选学校'?'amber':''}">${r.level}</span></td><td>${s.name}</td><td>${parentPhone(s)}</td><td>${s.school}</td><td>${s.grade}</td><td>${r.note}</td><td><button class="table-link" data-action="student-detail" data-id="${s.id}">档案 ›</button></td></tr>`}).join('');return `<div class="inline-info">${icon('shield')}　${screen==='families'?'家长可关联多个学生，以下每行对应一位学生。':screen==='scores'?'每行对应一条科目成绩。年级筛选采用本原型的当前年级。':'每行对应一条学生意向，学校汇总按学生去重。'} 管理员仅查看与导出。</div><section class="panel">${filterHTML()}<div class="table-toolbar"><span>查询结果 <strong>${all.length}</strong> 条${Object.values(filters).some(Boolean)?' · 已应用筛选条件':''}</span><button class="secondary" data-action="export">${icon('download')} 导出当前结果</button></div><div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table>${!rows.length?'<div class="empty">没有符合条件的记录<br>调整筛选条件或点击重置后重试。</div>':''}</div>${pager}</section>`}
function analysis(){return `<div class="inline-info">${icon('chart')}　以下图表描述填报数据分布。不同年级与考试的成绩不用于直接排名。</div>${chartPanels()}<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>意向学校汇总</h2><p>同一学生对同一学校按一位学生计数</p></div></div><div class="panel-body">${schoolBars()}</div></section><section class="panel"><div class="panel-head"><div><h2>各学校意向等级</h2><p>按意向记录计数</p></div></div><div class="panel-body"><div class="table-wrap"><table><thead><tr><th>学校</th>${levels.map(l=>`<th>${l}</th>`).join('')}</tr></thead><tbody>${schoolNames.map(n=>`<tr><td>${n}</td>${levels.map(l=>`<td>${intents.filter(i=>i.name===n&&i.level===l).length}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div></section></div>`}
function render(){if(!logged())return loginPage();root.innerHTML=`<div class="mobile-backdrop ${menuOpen?'open':''}" data-action="menu"></div><aside class="sidebar ${menuOpen?'open':''}">${brand()}<div class="nav-label">工作台 / WORKSPACE</div>${[['overview','grid'],['families','users'],['scores','book'],['intents','school'],['analysis','chart']].map(([s,i])=>`<button class="nav-item ${screen===s?'active':''}" data-action="nav" data-value="${s}" ${screen===s?'aria-current="page"':''}>${icon(i)}${titles[s]}</button>`).join('')}<div class="sidebar-bottom"><div class="privacy-card">${icon('shield')}<strong>每一份记录，妥善相待</strong>当前为设计体验版。<br>使用虚构数据，未连接后台服务。</div><a href="/" target="_blank" rel="noopener">${icon('arrow')} 查看家长端</a></div></aside><main class="workspace"><header class="topbar"><div class="crumb"><button class="mobile-menu" data-action="menu" aria-label="展开导航">${icon('menu')}</button><span>管理工作台</span><span>/</span><strong>${titles[screen]}</strong></div><div class="top-account"><span class="tag gray">设计体验版</span><span class="avatar">管</span><div style="font-size:11px">管理员<small>全局查看权限</small></div><button class="logout" data-action="logout" aria-label="退出登录">${icon('logout')}</button></div></header><div class="content"><div class="page-heading"><div><div class="eyebrow">${screen==='overview'?'A LITTLE CLARITY, A BIGGER PICTURE':'GROWTH ARCHIVE / ADMIN'}</div><h1>${screen==='overview'?'每一份成长，清晰可见':titles[screen]}</h1><p>${screen==='overview'?'查看家长填报情况，了解学生成绩与下一站的期待。':screen==='families'?'全局查看家长关联关系与学生档案。':screen==='scores'?'按家长、学校和年级查询每一条成绩记录。':screen==='intents'?'汇集每位学生的意向，了解学校选择与关注方向。':'从科目表现、等级与学校意向，查看整体填报分布。'}</p></div><div class="heading-actions">${screen==='overview'?'<span class="date-label">示例截至 2026年10月11日</span><button class="secondary" data-action="export-all">'+icon('download')+' 导出全量数据</button>':screen==='analysis'?'<button class="secondary" data-action="export-all">'+icon('download')+' 导出全量数据</button>':''}</div></div>${screen==='overview'?overview():screen==='analysis'?analysis():listPage()}<footer class="footer"><span>成长档案 · 管理工作台</span><span>演示数据 / 仅供交互体验</span></footer></div></main>`}
function openDrawer(title,sub,body){drawerRoot.innerHTML=`<div class="drawer-overlay"><section class="drawer" role="dialog" aria-modal="true" aria-label="${escapeHTML(title)}"><header class="drawer-head"><div><h2>${escapeHTML(title)}</h2><p>${escapeHTML(sub)}</p></div><button class="close" data-action="close-drawer" aria-label="关闭详情">×</button></header><div class="drawer-body">${body}</div><footer class="drawer-footer">${icon('shield')}　数据由家长自主填报，管理员仅查看。</footer></section></div>`;document.body.style.overflow='hidden';drawerRoot.querySelector('button').focus()}
function closeDrawer(){drawerRoot.innerHTML='';document.body.style.overflow=''}
function studentDetail(key){const s=studentBy(key),p=parentBy(s);openDrawer(s.name,'学生档案与关联记录',`<div class="detail-card"><div class="table-person"><span class="avatar">${s.name.slice(-1)}</span><h3>${s.name}</h3><span class="tag">${s.grade}</span></div><div class="detail-fields">${[['性别',s.gender],['就读学校',s.school],['入学年份',s.year],['入学年级',s.entry],['家长手机号',p.phone],['家长注册日期',p.date]].map(([k,v])=>`<div><label>${k}</label><span>${v}</span></div>`).join('')}</div></div><div class="detail-card"><h3>考试记录</h3>${exams.filter(e=>e.student===key).map(e=>`<div class="detail-row"><div>${e.name}<p class="muted" style="font-size:10px;margin-top:6px">${e.date} · ${e.subjects.length} 个科目</p></div><button class="table-link" data-action="exam-detail" data-id="${e.id}">查看 ›</button></div>`).join('')}</div><div class="detail-card"><h3>意向学校</h3>${intents.filter(i=>i.student===key).map(i=>`<div class="detail-row"><div>${i.name}<p class="muted" style="font-size:10px;margin-top:6px">${i.note}</p></div><span class="tag">${i.level}</span></div>`).join('')}</div>`)}
function examDetail(key){let e=exams.find(e=>e.id===key),s=studentBy(e.student);openDrawer(e.name,`${s.name} · ${s.school} · ${e.date}`,`<div class="detail-card"><div class="detail-fields" style="margin-top:0"><div><label>学生</label><span>${s.name}</span></div><div><label>家长手机号</label><span>${parentPhone(s)}</span></div></div></div><div class="detail-card"><h3>科目成绩</h3>${e.subjects.map(r=>`<div class="detail-row"><span>${r.name} <span class="tag gray">${r.type==='score'?'分数':'等级'}</span></span><strong>${r.type==='score'?`${r.score} <span class="muted">/ ${r.max}</span>`:r.grade}</strong></div>`).join('')}</div><div class="detail-card"><h3>备注</h3><p class="muted" style="font-size:12px;line-height:1.8;margin-top:12px">${e.note||'暂无备注'}</p></div>`)}
function csvValue(v){let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function downloadCSV(filename,rows){let blob=new Blob(['\uFEFF'+rows.map(row=>row.map(csvValue).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportData(type,all=false){let rows;if(type==='families'){rows=[['学生ID','学生姓名','性别','家长手机号','就读学校','当前年级','入学年份','入学年级'],...(all?students:filteredRows()).map(s=>[s.id,s.name,s.gender,parentPhone(s),s.school,s.grade,s.year,s.entry])]}else if(type==='scores'){rows=[['考试ID','学生ID','学生姓名','家长手机号','就读学校','当前年级','考试名称','日期','科目','类型','满分','分数','等级'],...(all?scoreRows:filteredRows()).map(r=>{let s=studentBy(r.exam.student);return [r.exam.id,s.id,s.name,parentPhone(s),s.school,s.grade,r.exam.name,r.exam.date,r.name,r.type==='score'?'分数':'等级',r.max??'',r.score??'',r.grade??'']})]}else{rows=[['学生ID','学生姓名','家长手机号','就读学校','当前年级','意向学校','意向等级','备注'],...(all?intents:filteredRows()).map(i=>{let s=studentBy(i.student);return [s.id,s.name,parentPhone(s),s.school,s.grade,i.name,i.level,i.note]})]}downloadCSV(`${titles[type]}${all?'_全部':'_筛选结果'}.csv`,rows);notify(`已导出 ${rows.length-1} 条记录（CSV）`)}
function exportDialog(){openDrawer('导出全量数据','选择数据类型，下载 CSV 文件',`<div class="inline-info">CSV 可使用 Excel 打开。本原型分别导出三类数据。</div>${['families','scores','intents'].map(type=>`<div class="detail-card"><h3>${titles[type]}</h3><p class="muted" style="font-size:11px;margin:12px 0">${type==='families'?students.length:type==='scores'?scoreRows.length:intents.length} 条记录 · 包含关联学生与家长信息</p><button class="primary" data-action="export-type" data-value="${type}">${icon('download')} 下载 CSV</button></div>`).join('')}`)}
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='login-form'){let fd=new FormData(e.target);if(fd.get('username')!=='admin'||fd.get('password')!=='demo123'){document.getElementById('login-error').textContent='体验账号或密码不正确，请使用 admin / demo123。';return}try{sessionStorage.setItem('admin-demo-session','1')}catch{document.getElementById('login-error').textContent='浏览器会话存储不可用，请允许网站存储后重试。';return}render();notify('已进入管理后台体验版')}else if(e.target.id==='filter-form'){filters=Object.fromEntries(new FormData(e.target));filters.phone=filters.phone.trim();currentPage=1;render()}});
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let {action:a,value:v,id:k}=b.dataset;switch(a){case'fill-demo':document.querySelector('[name="username"]').value='admin';document.querySelector('[name="password"]').value='demo123';break;case'toggle-password':{let i=document.querySelector('[name="password"]');i.type=i.type==='password'?'text':'password';b.setAttribute('aria-label',i.type==='password'?'显示密码':'隐藏密码');break}case'nav':navigate(v);break;case'chart':chartMode=v;render();break;case'logout':sessionStorage.removeItem('admin-demo-session');closeDrawer();screen='overview';loginPage();break;case'menu':menuOpen=!menuOpen;render();break;case'reset-filters':filters={};currentPage=1;render();break;case'page':currentPage=Number(v);render();break;case'student-detail':studentDetail(k);break;case'exam-detail':examDetail(k);break;case'close-drawer':closeDrawer();break;case'export':exportData(screen);break;case'export-all':exportDialog();break;case'export-type':exportData(v,true);break}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();if(e.key==='Tab'&&drawerRoot.firstChild){let controls=[...drawerRoot.querySelectorAll('button,a')];if(e.shiftKey&&document.activeElement===controls[0]){e.preventDefault();controls.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===controls.at(-1)){e.preventDefault();controls[0].focus()}}});render();
